  "colorutils": "float luma(float color){return color;}float luma(vec3 color){return dot(color,vec3(0.299,0.587,0.114));}float luma(vec4 color){return dot(color.rgb,vec3(0.299,0.587,0.114));}vec3 rgb2hsv(vec3 c){vec4 K=vec4(0.0,-1.0/3.0,2.0/3.0,-1.0);vec4 p=mix(vec4(c.bg,K.wz),vec4(c.gb,K.xy),step(c.b,c.g));vec4 q=mix(vec4(p.xyw,c.r),vec4(c.r,p.yzx),step(p.x,c.r));float d=q.x-min(q.w,q.y);float e=1.0e-10;return vec3(abs(q.z+(q.w-q.y)/(6.*d+e)),d/(q.x+e),q.x);}vec4 rgb2hsv(vec4 c){return vec4(rgb2hsv(c.rgb),c.a);}vec3 hsv2rgb(vec3 c){vec3 rgb=clamp(abs(mod(c.x*6.+vec3(0.,4.,2.),6.)-3.)-1.,0.,1.);return c.z*mix(vec3(1.),rgb,c.y);}vec4 hsv2rgb(vec4 c){return vec4(hsv2rgb(c.rgb),c.a);}vec4 rgbshift(sampler2D tex,vec2 uv,float angle,float amount){vec2 offset=amount*vec2(cos(angle),sin(angle));vec4 cr=texture2D(tex,uv+offset);vec4 cga=texture2D(tex,uv);vec4 cb=texture2D(tex,uv-offset);return vec4(cr.r,cga.g,cb.b,cga.a);}vec3 colorpalette(float t,vec3 a,vec3 b,vec3 c,vec3 d){return a+b*cos(6.28318*(c*t+d));}vec4 colorpalette(float t,vec4 a,vec4 b,vec4 c,vec4 d){return a+b*cos(6.28318*(c*t+d));}float brightnessContrast(float color,float brightness,float contrast){return(color-0.5)*contrast+0.5+brightness;}vec3 brightnessContrast(vec3 color,float brightness,float contrast){return(color-0.5)*contrast+0.5+brightness;}vec4 brightnessContrast(vec4 color,float brightness,float contrast){return vec4(brightnessContrast(color.rgb,brightness,contrast),color.a);}vec3 saturation(vec3 color,float adjustment){const vec3 W=vec3(0.2125,0.7154,0.0721);vec3 intensity=vec3(dot(color,W));return mix(intensity,color,adjustment);}vec4 saturation(vec4 color,float adjustment){return vec4(saturation(color.rgb,adjustment),color.a);}vec3 vibrance(vec3 color,float v){float average=(color.r+color.g+color.b)/3.0;float mx=max(color.r,max(color.g,color.b));float amt=(mx-average)*(-v*3.0);return mix(color.rgb,vec3(mx),amt);}vec4 vibrance(vec4 color,float v){return vec4(vibrance(color.rgb,v),color.a);}",
