  "vertexanimation": "attribute float vposition;uniform float time;uniform vec4 uAnimInfo;vec3 getAnimData(sampler2D map,float timeOffset){float t=mod((time+timeOffset)*uAnimInfo.x,uAnimInfo.y);float base=floor(t);float next=mod(floor(t+1.0),uAnimInfo.y);float weight=t-base;float p1=(base*uAnimInfo.z+vposition)/uAnimInfo.w;float p2=(next*uAnimInfo.z+vposition)/uAnimInfo.w;vec3 f1=texture2D(map,vec2(fract(p1),floor(p1)/uAnimInfo.w)).rgb;vec3 f2=texture2D(map,vec2(fract(p2),floor(p2)/uAnimInfo.w)).rgb;return mix(f1,f2,weight);}"
