    "vertexShader": "\n                //- edit\n                uniform mat4 textureMatrix;\n\n                \n// --- BEGIN CHUNK: globalUBO ---\nuniform Global{vec2 resolution;float time;float dtRatio;};\n// --- END CHUNK: globalUBO ---\n\n\n                varying vec4 vCoord;\n                varying vec3 vNormal;\n                varying vec3 wPos;\n                varying vec3 vPos;\n                varying vec2 vUv;\n\n                void main() {\n                    vUv = uv;\n                    vNormal = normalize(normalMatrix * normal);\n                    vCoord = textureMatrix * vec4(position, 1.0);\n\n                    float up = (sin(time * 0.5 + 23.124) + sin(time * 0.15 + 3213.32)) * 0.2;\n                    vec3 pos = (modelMatrix * vec4(position, 1.0)).xyz + vec3(0.0, up, 0.0);\n                    wPos = pos;\n                    vec4 viewPos = viewMatrix * vec4(pos, 1.0);\n\n                    vPos = viewPos.xyz;\n                    gl_Position = projectionMatrix * viewPos;\n                }\n            ",
